"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

Step 0 item 2 (P1 v0.4, sections 4.4 and 5.2): the real half of the TV or radio voices, from VoxPopuli.

Source: the English test file of facebook/voxpopuli at revision 42f01879 (CC0; European Parliament plenary speech).
It is not in MUSAN (whose speech part is LibriVox and US government hearings) and not in VoxTurn's training mixture
(technical report, Table 2: Smart Turn v3.2, Easy Turn, MagicData-RAMC, SpokenWOZ, Seamless Interaction, SemanticVAD,
MUSAN and VocalSound). Qwen3-ASR's training data is undisclosed (limitation, plan 8.4).

Utterances of 6-20 s are decoded and resampled to 16 kHz mono, at most 8 per speaker. Speakers are split train 50%,
dev 15%, test 20%, replication 15% (seeded, stratified by gender), so a TV speaker never crosses splits. The parquet is
downloaded data: read with python -I, path passed as an argument.
Writes data/tv_speech/<split>/<speaker>_<n>.wav and results/step0_v04/tv_speech.json.
usage: python -I scripts/step0v4_tv_speech.py <parquet>
"""
import io
import json
import os
import random
import sys
from collections import Counter, defaultdict

import numpy as np
import pyarrow.parquet as pq
import soundfile as sf
from scipy.signal import resample_poly

OUT = "data/tv_speech"
SEED = 20261115
SR = 16000


def main(path):
    f = pq.ParquetFile(path)
    rows = []
    for g in range(f.num_row_groups):
        rows += f.read_row_group(g, columns=["audio_id", "audio", "gender", "speaker_id", "normalized_text"]).to_pylist()
    by_spk = defaultdict(list)
    for r in rows:
        x, sr = sf.read(io.BytesIO(r["audio"]["bytes"]), dtype="float32", always_2d=True)
        dur = len(x) / sr
        if 6.0 <= dur <= 20.0:
            by_spk[r["speaker_id"]].append((r, x.mean(1), sr, dur))
    rng = random.Random(SEED)
    speakers = {}
    for gender in ("female", "male", "other"):
        spk = sorted(s for s, v in by_spk.items() if (v[0][0]["gender"] or "other") == gender
                     or (gender == "other" and v[0][0]["gender"] not in ("female", "male")))
        rng.shuffle(spk)
        n = len(spk)
        cut = [round(n * 0.50), round(n * 0.65), round(n * 0.85)]
        for i, s in enumerate(spk):
            speakers[s] = "train" if i < cut[0] else "dev" if i < cut[1] else "test" if i < cut[2] else "replication"
    manifest = {}
    for s, items in sorted(by_spk.items()):
        sp = speakers[s]
        os.makedirs(os.path.join(OUT, sp), exist_ok=True)
        items = sorted(items, key=lambda t: t[0]["audio_id"])[:8]
        for n, (r, x, sr, dur) in enumerate(items):
            g = np.gcd(sr, SR)
            y = resample_poly(x, SR // g, sr // g).astype(np.float32)
            name = f"{s}_{n}"
            p = os.path.join(OUT, sp, name + ".wav")
            sf.write(p, y, SR, subtype="PCM_16")
            manifest[name] = {"path": p.replace("\\", "/"), "speaker": s, "split": sp, "gender": r["gender"],
                              "dur_s": round(dur, 2), "audio_id": r["audio_id"], "text": r["normalized_text"]}
    table = {sp: {"speakers": len({m["speaker"] for m in manifest.values() if m["split"] == sp}),
                  "utterances": sum(m["split"] == sp for m in manifest.values()),
                  "gender": dict(Counter(manifest[k]["gender"] for k in manifest if manifest[k]["split"] == sp))}
             for sp in ("train", "dev", "test", "replication")}
    json.dump({"source": "facebook/voxpopuli en test, rev 42f01879c780b4a2e90ec0b4f616c2ece526e4f1 (CC0)",
               "seed": SEED, "table": table, "manifest": manifest},
              open("results/step0_v04/tv_speech.json", "w", encoding="utf-8"), indent=1, ensure_ascii=False)
    print("utterances 6-20 s:", sum(len(v) for v in by_spk.values()), "speakers:", len(by_spk))
    for sp, t in table.items():
        print(sp, t)


if __name__ == "__main__":
    main(sys.argv[1])
